def extended_gcd(a, b):
    r0, r1 = a, b
    s0, s1 = 1, 0
    t0, t1 = 0, 1
    while r1:
        q = r0 // r1
        r0, r1 = r1, r0 - q * r1
        s0, s1 = s1, s0 - q * s1
        t0, t1 = t1, t0 - q * t1
    return r0, s0


def factorial_coeffs(n, M):
    coeffs = [0] * (n + 1)
    coeffs[n] = 1
    for k in range(n - 1, -1, -1):
        coeffs[k] = (coeffs[k + 1] * (k + 1)) % M
        if not coeffs[k]:
            break
    return coeffs


def compute_app(n, M):
    K = [[[1]]]
    for i in range(n - 1):
        prev_layer = K[i]
        size_prev = len(prev_layer)
        new_layer = [[0] * (i + 2) for _ in range(size_prev + i + 1)]
        K.append(new_layer)
        for j, row in enumerate(prev_layer):
            for k, val in enumerate(row):
                for h in range(i + 1):
                    new_layer[j + h][k] = (new_layer[j + h][k] + val) % M
                new_layer[j + i + 1][i + 1] = (new_layer[j + i + 1][i + 1] + val) % M

    C = factorial_coeffs(n, M)
    total_sum = 0
    for i in range(1, n):
        current_layer = K[i]
        ni = len(current_layer)
        mi = len(current_layer[0])
        S = [[current_layer[j][k] for k in range(mi)] for j in range(ni)]
        for j in range(ni):
