                S[j][k] = (S[j][k] + S[j][k + 1]) % M
        for j in range(1, ni):
            for k in range(mi):
                S[j][k] = (S[j][k] + S[j - 1][k]) % M
        s_value = 0
        for j in range(1, ni):
            for k in range(mi - 1):
                s_value += (current_layer[j][k] * S[j - 1][k + 1]) % M
                s_value %= M
        c = C[i + 1]
        s_value = (s_value * c) % M
        total_sum = (total_sum + s_value) % M
    return total_sum


