import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        System.out.println(computeApp(n, m));
    }

    static long extendedGCD(long a, long b) {
        long r0 = a, r1 = b;
        long s0 = 1, s1 = 0;
        long t0 = 0, t1 = 1;
        while (r1 != 0) {
            long q = r0 / r1;
            long rTemp = r0 - q * r1;
            r0 = r1;
            r1 = rTemp;

            long sTemp = s0 - q * s1;
            s0 = s1;
            s1 = sTemp;

            long tTemp = t0 - q * t1;
            t0 = t1;
            t1 = tTemp;
        }
        return r0; // gcd
    }

    static long[] factorialCoeffs(int n, int M) {
        long[] coeffs = new long[n + 1];
        Arrays.fill(coeffs, 0);
        coeffs[n] = 1;
        for (int k = n - 1; k >= 0; k--) {
            coeffs[k] = (coeffs[k + 1] * (k + 1)) % M;
            if (coeffs[k] == 0) {
                break;
            }
        }
        return coeffs;
    }

    static long computeApp(int n, int M) {
        List<List<long[]>> K = new ArrayList<>();
        List<long[]> firstLayer = new ArrayList<>();
        firstLayer.add(new long[]{1});
        K.add(firstLayer);

        for (int i = 0; i < n - 1; i++) {
            List<long[]> prevLayer = K.get(i);
            int sizePrev = prevLayer.size();
            List<long[]> newLayer = new ArrayList<>();
            int rows = sizePrev + i + 1;
            int cols = i + 2;
            for (int j = 0; j < rows; j++) {
                newLayer.add(new long[cols]);
            }
            for (int j = 0; j < sizePrev; j++) {
                long[] row = prevLayer.get(j);
                for (int k = 0; k < row.length; k++) {
                    long val = row[k];
                    for (int h = 0; h < i + 1; h++) {
                        newLayer.get(j + h)[k] = (newLayer.get(j + h)[k] + val) % M;
                    }
                    newLayer.get(j + i + 1)[i + 1] = (newLayer.get(j + i + 1)[i + 1] + val) % M;
                }
            }
            K.add(newLayer);
        }

        long[] C = factorialCoeffs(n, M);
        long totalSum = 0;

        for (int i = 1; i < n; i++) {
            List<long[]> currentLayer = K.get(i);
            int ni = currentLayer.size();
            int mi = currentLayer.get(0).length;

            long[][] S = new long[ni][mi];
            for (int j = 0; j < ni; j++) {
                System.arraycopy(currentLayer.get(j), 0, S[j], 0, mi);
            }

            for (int j = 0; j < ni; j++) {
                for (int k = mi - 2; k >= 0; k--) {
                    S[j][k] = (S[j][k] + S[j][k + 1]) % M;
                }
            }

            for (int j = 1; j < ni; j++) {
                for (int k = 0; k < mi; k++) {
                    S[j][k] = (S[j][k] + S[j - 1][k]) % M;
                }
            }

            long s_value = 0;
            for (int j = 1; j < ni; j++) {
                for (int k = 0; k < mi - 1; k++) {
                    s_value += (currentLayer.get(j)[k] * S[j - 1][k + 1]) % M;
                    s_value %= M;
                }
            }

            long c = C[i + 1];
            s_value = (s_value * c) % M;
            totalSum = (totalSum + s_value) % M;
        }
        return totalSum;
    }
}
